# 301 redirects: "$host$uri" (decoded, no query string) → absolute URL.
# In the http block:
#
#     map_hash_bucket_size 256;
#     map $host$uri $darc_redirect {
#         default "";
#         include /path/to/contrib/nginx.map;
#     }
#
# and in the openaleph.org and dataresearchcenter.org server blocks:
#
#     if ($darc_redirect) {
#         return 301 $darc_redirect;
#     }
#
# Keys use bare hosts (redirect www.* first). openaleph.org/docs/ isn't listed.

